"""Join junction patches and approach surfaces by explicit mouth identities.

Only original boundary vertices on a declared finite mouth profile are eligible.
Each mouth must have its full expected sample count on both surfaces. Matching
vertices are welded in integer identity space after checking physical agreement;
unrelated close vertices are not merged. The junction component may contain
several patches when all mouths use the same globally unique source indices.
"""
from . import boundary_quad_bridge_nodes as bridge


def construct(g, junction, approaches, mouths, factor, *, exact_weld=False):
    index=g.node('GeometryNodeInputIndex','Original component vertex').outputs[0]
    pos=g.node('GeometryNodeInputPosition','Physical seam vertex').outputs[0]
    count=bridge._size(g,mouths)
    expected=g.stat(mouths,g.math('ADD',1.,g.math('MULTIPLY',factor,g.named('st_mouth_segments'))),output='Sum')
    parts=[];checks=[g.compare(count,0,'GREATER_THAN')]
    for component,geometry in enumerate((junction,approaches)):
        geometry=g.store(geometry,'_bridge_key',g.xyz(component,index,0.),'FLOAT_VECTOR')
        # The vertex incident-face count equals degree-1 exactly on the open
        # manifold quad strips and patches accepted by the component guards.
        neighbors=g.node('GeometryNodeInputMeshVertexNeighbors','Exposed manifold boundary vertices')
        is_boundary=g.compare(neighbors.outputs['Vertex Count'],g.math('ADD',neighbors.outputs['Face Count'],1.))
        geometry=g.store(geometry,'_profile_boundary',is_boundary,'BOOLEAN')
        geometry=g.store(geometry,'_profile_matches',0,'INT')
        ri=g.node('GeometryNodeRepeatInput','Bind each explicit member mouth')
        ro=g.node('GeometryNodeRepeatOutput','Component with integer profile seam identities')
        ro.repeat_items.clear();ro.repeat_items.new('GEOMETRY','Mesh');ro.repeat_items.new('BOOLEAN','Valid')
        ri.pair_with_output(ro);g.set(count,ri.inputs['Iterations']);g.set(geometry,ri.inputs['Mesh'])
        ri.inputs['Valid'].default_value=True
        def mouth(name,kind='FLOAT'):
            return g.sample(mouths,g.named('st_mouth_'+name,kind),ri.outputs['Iteration'],kind)
        center=mouth('position','FLOAT_VECTOR');lateral=mouth('lateral','FLOAT_VECTOR')
        axis=mouth('cut_axis','FLOAT_VECTOR');width=mouth('width')
        relative=g.vector('SUBTRACT',pos,center)
        along=g.vector('DOT_PRODUCT',relative,axis)
        u=g.math('ADD',.5,g.math('DIVIDE',g.vector('DOT_PRODUCT',relative,lateral),
            g.math('MULTIPLY',width,g.vector('DOT_PRODUCT',lateral,lateral))))
        n=g.math('MULTIPLY',mouth('segments','INT'),factor)
        rank=g.math('ROUND',g.math('MULTIPLY',u,n))
        # The transverse row is straight even at an oblique mouth. A residual
        # check excludes a different boundary crossing the same infinite plane.
        # Compare to the finite *sample*, using the same metre tolerance at
        # profile endpoints and inside the row. A fixed u epsilon rejected
        # narrow profiles after harmless micrometre float rounding at a
        # translated junction. Rank bounds keep the finite profile exact.
        sample_u=g.math('DIVIDE',rank,g.math('MAXIMUM',n,1.))
        on_line=g.vector('SCALE',lateral,g.math('MULTIPLY',g.math('SUBTRACT',sample_u,.5),width))
        residual=g.vector('SUBTRACT',relative,on_line)
        xy_error=g.vector('LENGTH',g.xyz(g.component(residual,'X'),g.component(residual,'Y')))
        selected=g.all(g.named('_profile_boundary','BOOLEAN'),g.compare(g.math('ABSOLUTE',along),bridge.TOLERANCE,'LESS_EQUAL'),
            g.compare(xy_error,bridge.TOLERANCE,'LESS_EQUAL'),g.compare(rank,0.,'GREATER_EQUAL'),g.compare(rank,n,'LESS_EQUAL'),
            g.close(g.math('MULTIPLY',u,n),rank,1e-3))
        current=ri.outputs['Mesh']
        # Test every mouth independently. A total alone could hide a missing
        # sample at one mouth and an extra sample at a different mouth.
        g.set(g.all(ri.outputs['Valid'],g.compare(width,0.,'GREATER_THAN'),
            g.compare(g.stat(current,selected,output='Sum'),g.math('ADD',n,1.))),ro.inputs['Valid'])
        current=g.store(current,'_bridge_key',g.switch(selected,g.named('_bridge_key','FLOAT_VECTOR'),
            g.xyz(2.,mouth('key','INT'),rank),'VECTOR'),'FLOAT_VECTOR')
        current=g.store(current,'_profile_matches',g.math('ADD',g.named('_profile_matches'),selected),'INT')
        g.set(current,ro.inputs['Mesh']);bound=ro.outputs['Mesh']
        checks.extend((ro.outputs['Valid'],g.compare(g.stat(bound,g.named('_profile_matches'),output='Max'),1.,'LESS_EQUAL'),
            g.compare(g.stat(bound,g.named('_profile_matches'),output='Sum'),expected)))
        parts.append(bound)
    combined=bridge._join(g,*parts);mesh,agreement=bridge._weld(g,combined,exact_reference=exact_weld)
    checks.extend((agreement,g.compare(g.math('SUBTRACT',bridge._size(g,combined),bridge._size(g,mesh)),expected)))
    return mesh,g.all(*checks)
